        sol: "#include \"main.h\"\n\n/**\n * _strstr - locate substring\n * @haystack: string\n * @needle: substring\n *\n * Return: pointer or NULL\n */\nchar *_strstr(char *haystack, char *needle)\n{\n\tint i;\n\n\tfor (; *haystack; haystack++)\n\t{\n\t\tfor (i = 0; needle[i] && haystack[i] == needle[i]; i++)\n\t\t\t;\n\t\tif (!needle[i])\n\t\t\treturn (haystack);\n\t}\n\treturn (*needle ? NULL : haystack);\n}\n",
