        sol: "#include \"main.h\"\n\n/**\n * print_diagsums - sums of diagonals\n * @a: matrix\n * @size: size\n */\nvoid print_diagsums(int *a, int size)\n{\n\tint i, s1 = 0, s2 = 0;\n\n\tfor (i = 0; i < size; i++)\n\t{\n\t\ts1 += a[i * size + i];\n\t\ts2 += a[i * size + (size - 1 - i)];\n\t}\n\tprintf(\"%d, %d\\n\", s1, s2);\n}\n",
