        sol: "#include \"main.h\"\n\n/**\n * check_div - helper\n * @n: number\n * @d: divisor\n *\n * Return: 1 if prime\n */\nint check_div(int n, int d)\n{\n\tif (d * d > n)\n\t\treturn (1);\n\tif (n % d == 0)\n\t\treturn (0);\n\treturn (check_div(n, d + 1));\n}\n\n/**\n * is_prime_number - prime test\n * @n: number\n *\n * Return: 1 or 0\n */\nint is_prime_number(int n)\n{\n\tif (n < 2)\n\t\treturn (0);\n\treturn (check_div(n, 2));\n}\n",
