  EX["ll-10"] = {
    quiz: [
      ["Which header provides va_list, va_start, va_arg and va_end?", ["stdlib.h", "stdarg.h", "stdio.h", "varargs.h only"], 1],
      ["What must <code>va_start</code> be given?", ["The va_list and the last named parameter", "The number of arguments", "The first variadic argument", "Nothing"], 0],
      ["What type should you use in <code>va_arg(ap, ...)</code> to read a <code>char</code> argument?", ["char", "int", "char *", "short"], 1, "Default argument promotions turn char (and short) into int, and float into double."],
      ["Why use the <code>const</code> keyword on a parameter?", ["To make it faster", "To promise the function won't modify it", "To make it global", "To allow NULL"], 1],
    ],
    tasks: [
      { t: "Beauty is variable, ugliness is constant (sum_them_all)", lang: "c", file: "0-sum_them_all.c", header: "int sum_them_all(const unsigned int n, ...);\n",
        p: `<p>Return the sum of all its parameters. If n == 0, return 0. Prototype: <code>int sum_them_all(const unsigned int n, ...);</code></p>`,
        start: stub("int sum_them_all(const unsigned int n, ...)", "returns the sum of all its parameters"),
        sol: "#include <stdarg.h>\n#include \"variadic_functions.h\"\n\n/**\n * sum_them_all - sum of args\n * @n: count\n *\n * Return: sum\n */\nint sum_them_all(const unsigned int n, ...)\n{\n\tva_list ap;\n\tunsigned int i;\n\tint s = 0;\n\n\tva_start(ap, n);\n\tfor (i = 0; i < n; i++)\n\t\ts += va_arg(ap, int);\n\tva_end(ap);\n\treturn (s);\n}\n",
        tests: [{ main: "int main(void)\n{\n\tprintf(\"%d\\n\", sum_them_all(2, 98, 1024));\n\tprintf(\"%d\\n\", sum_them_all(4, 98, 1024, 402, -1024));\n\tprintf(\"%d\\n\", sum_them_all(0));\n\treturn (0);\n}\n", out: "1122\n500\n0\n" }] },
      { t: "Make it work, make it right, make it fast (print_numbers)", lang: "c", file: "1-print_numbers.c", header: "void print_numbers(const char *separator, const unsigned int n, ...);\n",
        p: `<p>Print numbers, followed by a new line. Prototype: <code>void print_numbers(const char *separator, const unsigned int n, ...);</code> <code>separator</code> is printed between numbers; if it's NULL, don't print it.</p>`,
        start: vstub("void print_numbers(const char *separator, const unsigned int n, ...)", "prints numbers"),
        sol: "#include <stdio.h>\n#include <stdarg.h>\n#include \"variadic_functions.h\"\n\n/**\n * print_numbers - prints numbers\n * @separator: between numbers\n * @n: count\n */\nvoid print_numbers(const char *separator, const unsigned int n, ...)\n{\n\tva_list ap;\n\tunsigned int i;\n\n\tva_start(ap, n);\n\tfor (i = 0; i < n; i++)\n\t{\n\t\tif (i && separator)\n\t\t\tprintf(\"%s\", separator);\n\t\tprintf(\"%d\", va_arg(ap, int));\n\t}\n\tva_end(ap);\n\tprintf(\"\\n\");\n}\n",
        tests: [{ main: "int main(void)\n{\n\tprint_numbers(\", \", 4, 0, 98, -1024, 402);\n\tprint_numbers(NULL, 3, 1, 2, 3);\n\tprint_numbers(\"-\", 0);\n\treturn (0);\n}\n", out: "0, 98, -1024, 402\n123\n\n" }] },
      { t: "To be is a to be the value of a variable (print_all)", lang: "c", file: "3-print_all.c", header: "void print_all(const char * const format, ...);\n", adv: true,
        p: `<p>Print anything. Prototype: <code>void print_all(const char * const format, ...);</code> <code>format</code> lists the argument types: <code>c</code> char, <code>i</code> integer, <code>f</code> float, <code>s</code> char * (print <code>(nil)</code> if NULL). Other letters are ignored. Values are separated by <code>, </code> and the output ends with a new line.</p>`,
        start: vstub("void print_all(const char * const format, ...)", "prints anything"),
        sol: "#include <stdio.h>\n#include <stdarg.h>\n#include \"variadic_functions.h\"\n\n/**\n * print_all - prints anything\n * @format: types\n */\nvoid print_all(const char * const format, ...)\n{\n\tva_list ap;\n\tint i = 0;\n\tchar *sep = \"\", *s;\n\n\tva_start(ap, format);\n\twhile (format && format[i])\n\t{\n\t\tif (format[i] == 'c')\n\t\t\tprintf(\"%s%c\", sep, va_arg(ap, int));\n\t\telse if (format[i] == 'i')\n\t\t\tprintf(\"%s%d\", sep, va_arg(ap, int));\n\t\telse if (format[i] == 'f')\n\t\t\tprintf(\"%s%f\", sep, va_arg(ap, double));\n\t\telse if (format[i] == 's')\n\t\t{\n\t\t\ts = va_arg(ap, char *);\n\t\t\tprintf(\"%s%s\", sep, s ? s : \"(nil)\");\n\t\t}\n\t\telse\n\t\t{\n\t\t\ti++;\n\t\t\tcontinue;\n\t\t}\n\t\tsep = \", \";\n\t\ti++;\n\t}\n\tva_end(ap);\n\tprintf(\"\\n\");\n}\n",
        tests: [{ main: "int main(void)\n{\n\tprint_all(\"ceis\", 'B', 3, \"stSchool\");\n\tprint_all(\"sfx\", NULL, 3.5);\n\treturn (0);\n}\n", out: "B, 3, stSchool\n(nil), 3.500000\n" }] },
    ],
  };

  /* ---------------- printf ---------------- */
  EX["printf"] = {
    quiz: [
      ["What does <code>printf</code> return?", ["0 on success", "The number of characters printed", "The format string", "void"], 1],
      ["Which conversion specifier prints a percent sign?", ["\\%", "%%", "%p", "%c"], 1],
      ["What is printed by <code>printf(\"%x\", 255)</code>?", ["ff", "FF", "377", "11111111"], 0],
      ["Why buffer output in a local buffer of 1024 chars?", ["printf requires it", "Fewer write() system calls = faster", "To support %s", "To handle negative numbers"], 1],
      ["What should <code>_printf(NULL)</code> return?", ["0", "-1", "It should crash", "1"], 1],
    ],
    tasks: [
      { t: "I'm not going anywhere. You can print that wherever you want to. I'm here and I'm a Spur for life", lang: "c", file: "_printf.c", header: "int _printf(const char *format, ...);\n",
        p: `<p>Write a function that produces output according to a format. Prototype: <code>int _printf(const char *format, ...);</code> Return the number of characters printed (excluding the null byte), or -1 if format is NULL. Handle <code>%c</code>, <code>%s</code> (print <code>(null)</code> for NULL) and <code>%%</code>. Use <code>write</code> — not printf! Put all your helper functions in this file.</p>`,
        start: "#include <stdarg.h>\n#include <unistd.h>\n#include \"main.h\"\n\n/**\n * _printf - produces output according to a format\n * @format: format string\n *\n * Return: number of characters printed\n */\nint _printf(const char *format, ...)\n{\n\n}\n",
        sol: "#include <stdarg.h>\n#include <unistd.h>\n#include \"main.h\"\n\n/**\n * put_s - writes a string\n * @s: string\n *\n * Return: count\n */\nint put_s(char *s)\n{\n\tint n = 0;\n\n\tif (s == NULL)\n\t\ts = \"(null)\";\n\twhile (s[n])\n\t\tn++;\n\treturn (write(1, s, n));\n}\n\n/**\n * _printf - minimal printf\n * @format: format string\n *\n * Return: number of chars printed\n */\nint _printf(const char *format, ...)\n{\n\tva_list ap;\n\tint n = 0, i;\n\tchar c;\n\n\tif (format == NULL)\n\t\treturn (-1);\n\tva_start(ap, format);\n\tfor (i = 0; format[i]; i++)\n\t{\n\t\tif (format[i] != '%')\n\t\t{\n\t\t\tn += write(1, &format[i], 1);\n\t\t\tcontinue;\n\t\t}\n\t\ti++;\n\t\tif (format[i] == '\\0')\n\t\t{\n\t\t\tva_end(ap);\n\t\t\treturn (-1);\n\t\t}\n\t\tif (format[i] == 'c')\n\t\t{\n\t\t\tc = va_arg(ap, int);\n\t\t\tn += write(1, &c, 1);\n\t\t}\n\t\telse if (format[i] == 's')\n\t\t\tn += put_s(va_arg(ap, char *));\n\t\telse if (format[i] == '%')\n\t\t\tn += write(1, \"%\", 1);\n\t\telse\n\t\t{\n\t\t\tn += write(1, \"%\", 1);\n\t\t\tn += write(1, &format[i], 1);\n\t\t}\n\t}\n\tva_end(ap);\n\treturn (n);\n}\n",
        tests: [{ main: "int main(void)\n{\n\tint a, b;\n\n\ta = _printf(\"Let's try to printf a simple sentence.\\n\");\n\tb = printf(\"Let's try to printf a simple sentence.\\n\");\n\tfflush(stdout);\n\t_printf(\"Length:[%c%c]\\n\", a == b ? 'o' : 'x', 'k');\n\t_printf(\"Character:[%c]\\n\", 'H');\n\t_printf(\"String:[%s]\\n\", \"I am a string !\");\n\ta = _printf(\"Percent:[%%]\\n\");\n\t_printf(\"Len:[%s]\\n\", a == 12 ? \"12\" : \"wrong\");\n\t_printf(\"%s\\n\", NULL);\n\t_printf(\"%s\\n\", _printf(NULL) == -1 ? \"-1 for NULL\" : \"wrong\");\n\treturn (0);\n}\n", out: "Let's try to printf a simple sentence.\nLet's try to printf a simple sentence.\nLength:[ok]\nCharacter:[H]\nString:[I am a string !]\nPercent:[%]\nLen:[12]\n(null)\n-1 for NULL\n" }] },
      { t: "Education is when you read the fine print (%d and %i)", lang: "c", file: "_printf.c", header: "int _printf(const char *format, ...);\n",
        p: `<p>Extend your <code>_printf</code> (copy it over) to handle <code>%d</code> and <code>%i</code>. Don't forget negative numbers and <code>INT_MIN</code>.</p>`,
        start: "/* paste your _printf from the previous task and add %d / %i */\n",
        sol: "#include <stdarg.h>\n#include <unistd.h>\n#include \"main.h\"\n\n/**\n * put_num - prints an int\n * @n: number\n *\n * Return: count\n */\nint put_num(long n)\n{\n\tchar buf[24];\n\tint i = 0, c = 0;\n\n\tif (n < 0)\n\t{\n\t\tc += write(1, \"-\", 1);\n\t\tn = -n;\n\t}\n\tdo {\n\t\tbuf[i++] = '0' + n % 10;\n\t\tn /= 10;\n\t} while (n);\n\twhile (i--)\n\t\tc += write(1, &buf[i], 1);\n\treturn (c);\n}\n\n/**\n * put_s - writes a string\n * @s: string\n *\n * Return: count\n */\nint put_s(char *s)\n{\n\tint n = 0;\n\n\tif (s == NULL)\n\t\ts = \"(null)\";\n\twhile (s[n])\n\t\tn++;\n\treturn (write(1, s, n));\n}\n\n/**\n * _printf - printf with c s % d i\n * @format: format\n *\n * Return: count\n */\nint _printf(const char *format, ...)\n{\n\tva_list ap;\n\tint n = 0, i;\n\tchar c;\n\n\tif (format == NULL)\n\t\treturn (-1);\n\tva_start(ap, format);\n\tfor (i = 0; format[i]; i++)\n\t{\n\t\tif (format[i] != '%')\n\t\t{\n\t\t\tn += write(1, &format[i], 1);\n\t\t\tcontinue;\n\t\t}\n\t\ti++;\n\t\tif (format[i] == 'c')\n\t\t{\n\t\t\tc = va_arg(ap, int);\n\t\t\tn += write(1, &c, 1);\n\t\t}\n\t\telse if (format[i] == 's')\n\t\t\tn += put_s(va_arg(ap, char *));\n\t\telse if (format[i] == 'd' || format[i] == 'i')\n\t\t\tn += put_num(va_arg(ap, int));\n\t\telse if (format[i] == '%')\n\t\t\tn += write(1, \"%\", 1);\n\t\telse if (format[i] == '\\0')\n\t\t\treturn (-1);\n\t\telse\n\t\t{\n\t\t\tn += write(1, \"%\", 1);\n\t\t\tn += write(1, &format[i], 1);\n\t\t}\n\t}\n\tva_end(ap);\n\treturn (n);\n}\n",
        tests: [{ main: "int main(void)\n{\n\tint a, b;\n\n\ta = _printf(\"Negative:[%d]\\n\", -762534);\n\tb = printf(\"Negative:[%d]\\n\", -762534);\n\tfflush(stdout);\n\t_printf(\"Same length: %d %d\\n\", a, b);\n\t_printf(\"%i %d %d\\n\", 0, 1024, INT_MIN);\n\t_printf(\"%d\\n\", INT_MAX);\n\treturn (0);\n}\n", out: "Negative:[-762534]\nNegative:[-762534]\nSame length: 19 19\n0 1024 -2147483648\n2147483647\n" }] },
      { t: "Just because it's in print doesn't mean it's the gospel (%b %u %o %x %X)", lang: "c", file: "_printf.c", header: "int _printf(const char *format, ...);\n", adv: true,
        p: `<p>Add the custom conversion specifier <code>%b</code> (unsigned int → binary) and <code>%u</code>, <code>%o</code>, <code>%x</code>, <code>%X</code>.</p>`,
        start: "/* paste your _printf and add %b %u %o %x %X */\n",
        sol: "#include <stdarg.h>\n#include <unistd.h>\n#include \"main.h\"\n\n/**\n * put_base - prints an unsigned number in a base\n * @n: number\n * @base: base\n * @digits: digit characters\n *\n * Return: count\n */\nint put_base(unsigned long n, unsigned int base, char *digits)\n{\n\tchar buf[72];\n\tint i = 0, c = 0;\n\n\tdo {\n\t\tbuf[i++] = digits[n % base];\n\t\tn /= base;\n\t} while (n);\n\twhile (i--)\n\t\tc += write(1, &buf[i], 1);\n\treturn (c);\n}\n\n/**\n * _printf - printf with b u o x X\n * @format: format\n *\n * Return: count\n */\nint _printf(const char *format, ...)\n{\n\tva_list ap;\n\tint n = 0, i;\n\tchar *lo = \"0123456789abcdef\", *up = \"0123456789ABCDEF\";\n\n\tif (format == NULL)\n\t\treturn (-1);\n\tva_start(ap, format);\n\tfor (i = 0; format[i]; i++)\n\t{\n\t\tif (format[i] != '%')\n\t\t{\n\t\t\tn += write(1, &format[i], 1);\n\t\t\tcontinue;\n\t\t}\n\t\ti++;\n\t\tif (format[i] == 'b')\n\t\t\tn += put_base(va_arg(ap, unsigned int), 2, lo);\n\t\telse if (format[i] == 'u')\n\t\t\tn += put_base(va_arg(ap, unsigned int), 10, lo);\n\t\telse if (format[i] == 'o')\n\t\t\tn += put_base(va_arg(ap, unsigned int), 8, lo);\n\t\telse if (format[i] == 'x')\n\t\t\tn += put_base(va_arg(ap, unsigned int), 16, lo);\n\t\telse if (format[i] == 'X')\n\t\t\tn += put_base(va_arg(ap, unsigned int), 16, up);\n\t\telse if (format[i] == '%')\n\t\t\tn += write(1, \"%\", 1);\n\t\telse if (format[i] == '\\0')\n\t\t\treturn (-1);\n\t}\n\tva_end(ap);\n\treturn (n);\n}\n",
        tests: [{ main: "int main(void)\n{\n\t_printf(\"%b\\n\", 98);\n\t_printf(\"%u %o %x %X\\n\", 4294967295U, 8, 255, 255);\n\t_printf(\"%b %u\\n\", 0, 0);\n\treturn (0);\n}\n", out: "1100010\n4294967295 10 ff FF\n0 0\n" }] },
    ],
    manual: ["Work with a partner: one GitHub repo, feature branches, pull requests", "Write the man page <code>man_3_printf</code> and view it with <code>man ./man_3_printf</code>", "Add the flags <code>+ space #</code>, length modifiers <code>l h</code>, field width and precision (advanced)"],
  };
